    private function readDcrInitialAccessToken(ServerRequestInterface $request): DcrInitialAccessTokenUpdateParams
    {
        $this->logDebug("Read entity for Dcr initial access token");
        $span = $this->startSpan("Read entity for Dcr initial access token");
        try {
            $parsed = $request->getParsedBody() ?? [];
            $body = is_array($parsed) ? $parsed : get_object_vars($parsed);
            $errorsList = new ConstraintFailList();
            $value = new DcrInitialAccessTokenUpdateParams();
            $valueUid = DcrInitialAccessTokenUidVO::tryFrom($body['uid'] ?? null, $errorsList);
            if (null !== $valueUid) {
                $value->uid($valueUid);
            }
            if (in_array('tenant', array_keys($body))) {
                $valueTenant = DcrInitialAccessTokenTenantVO::tryFrom(isset($body['tenant']['$ref']) ? new TenantRef($body['tenant']['$ref']) : null, $errorsList);
                if (null !== $valueTenant) {
                    $value->tenant($valueTenant);
                }
            }
            $value->description(DcrInitialAccessTokenDescriptionVO::tryFrom($body['description'] ?? null, $errorsList));
            $readTokenHash = $body['tokenHash'] ?? '******';
            if (null !== $readTokenHash && '******' !== $readTokenHash) {
                $valueTokenHash = DcrInitialAccessTokenTokenHashVO::tryFromPlainText($this->cypherService, $readTokenHash, $errorsList);
                if (null !== $valueTokenHash) {
                    $value->tokenHash($valueTokenHash);
                }
            }
            $valueExpiresAt = DcrInitialAccessTokenExpiresAtVO::tryFrom($body['expiresAt'] ?? null, $errorsList);
            if (null !== $valueExpiresAt) {
                $value->expiresAt($valueExpiresAt);
            }
            $valueMaxUses = DcrInitialAccessTokenMaxUsesVO::tryFrom($body['maxUses'] ?? null, $errorsList);
            if (null !== $valueMaxUses) {
                $value->maxUses($valueMaxUses);
            }
            $value->allowedGrantTypes(DcrInitialAccessTokenAllowedGrantTypesVO::tryFrom($body['allowedGrantTypes'] ?? null, $errorsList));
            $value->revokedAt(DcrInitialAccessTokenRevokedAtVO::tryFrom($body['revokedAt'] ?? null, $errorsList));
            $value->version(DcrInitialAccessTokenVersionVO::tryFrom($body['version'] ?? null, $errorsList));
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            return $value;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
